def smooth_l1_loss(input: torch.Tensor, target: torch.Tensor, beta: float,
    reduction: str='none') ->torch.Tensor:
    diff = input - target
    abs_diff = diff.abs()

    if beta < 1e-5:
        # When beta is very small, use the linear loss
        loss = abs_diff
    else:
        # Compute smooth L1 loss
        loss = torch.where(
            abs_diff < beta,
            0.5 * diff * diff / beta,
            abs_diff - 0.5 * beta
        )

    if reduction == 'none':
        return loss
    elif reduction == 'mean':
        return loss.mean()
    elif reduction == 'sum':
        return loss.sum()
    else:
        raise ValueError(f"Invalid reduction mode: {reduction}")
